18	package org.apache.hadoop.yarn.service.monitor.probe;
19	
20	import org.apache.hadoop.yarn.service.component.instance.ComponentInstance;
21	import org.slf4j.Logger;
22	import org.slf4j.LoggerFactory;
23	
24	import java.io.IOException;
25	import java.net.HttpURLConnection;
26	import java.net.URL;
27	import java.util.Map;
28	
29	/**
30	 * A probe that checks whether a successful HTTP response code can be obtained
31	 * from a container. A well-formed URL must be provided. The URL is intended
32	 * to contain a token ${THIS_HOST} that will be replaced by the IP of the
33	 * container. This probe also performs the checks of the {@link DefaultProbe}.
34	 * Additional configurable properties include:
35	 *
36	 *   url - required URL for HTTP connection, e.g. http://${THIS_HOST}:8080
37	 *   timeout - connection timeout (default 1000)
38	 *   min.success - minimum response code considered successful (default 200)
39	 *   max.success - maximum response code considered successful (default 299)
40	 *
41	 */
42	public class HttpProbe extends DefaultProbe {
43	  protected static final Logger log = LoggerFactory.getLogger(HttpProbe.class);
44	
45	  private static final String HOST_TOKEN = "${THIS_HOST}";
46	
47	  private final String urlString;
48	  private final int timeout;
49	  private final int min, max;
50	
51	
52	  public HttpProbe(String url, int timeout, int min, int max,
53	      Map<String, String> props) {
54	    super("Http probe of " + url + " [" + min + "-" + max + "]", props);
55	    this.urlString = url;
56	    this.timeout = timeout;
57	    this.min = min;
58	    this.max = max;
59	  }
60	
61	  public static HttpProbe create(Map<String, String> props)
62	      throws IOException {
63	    String urlString = getProperty(props, WEB_PROBE_URL, null);
64	    new URL(urlString);
65	    int timeout = getPropertyInt(props, WEB_PROBE_CONNECT_TIMEOUT,
66	        WEB_PROBE_CONNECT_TIMEOUT_DEFAULT);
67	    int minSuccess = getPropertyInt(props, WEB_PROBE_MIN_SUCCESS,
68	        WEB_PROBE_MIN_SUCCESS_DEFAULT);
69	    int maxSuccess = getPropertyInt(props, WEB_PROBE_MAX_SUCCESS,
70	        WEB_PROBE_MAX_SUCCESS_DEFAULT);
71	    return new HttpProbe(urlString, timeout, minSuccess, maxSuccess, props);
72	  }
73	
74	
75	  private static HttpURLConnection getConnection(URL url, int timeout) throws
76	      IOException {
77	    HttpURLConnection connection = (HttpURLConnection) url.openConnection();
78	    connection.setInstanceFollowRedirects(true);
79	    connection.setConnectTimeout(timeout);
80	    return connection;
81	  }
82	
83	  @Override
84	  public ProbeStatus ping(ComponentInstance instance) {
85	    ProbeStatus status = super.ping(instance);
86	    if (!status.isSuccess()) {
87	      return status;
88	    }
89	    String ip = instance.getContainerStatus().getIPs().get(0);
90	    HttpURLConnection connection = null;
91	    try {
92	      URL url = new URL(urlString.replace(HOST_TOKEN, ip));
93	      connection = getConnection(url, this.timeout);
94	      int rc = connection.getResponseCode();
95	      if (rc < min || rc > max) {
96	        String error = "Probe " + url + " error code: " + rc;
97	        log.info(error);
98	        status.fail(this,
99	            new IOException(error));
100	      } else {
101	        status.succeed(this);
102	      }
103	    } catch (Throwable e) {
104	      String error = "Probe " + urlString + " failed for IP " + ip + ": " + e;
105	      log.info(error, e);
106	      status.fail(this,
107	          new IOException(error, e));
108	    } finally {
109	      if (connection != null) {
110	        connection.disconnect();
111	      }
112	    }
113	    return status;
114	  }
115	}
