18	package org.apache.hadoop.yarn.service.monitor.probe;
19	
20	import org.apache.hadoop.io.IOUtils;
21	import org.apache.hadoop.yarn.service.component.instance.ComponentInstance;
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	
25	import java.io.IOException;
26	import java.net.InetSocketAddress;
27	import java.net.Socket;
28	import java.util.Map;
29	
30	/**
31	 * A probe that checks whether a container has a specified port open. This
32	 * probe also performs the checks of the {@link DefaultProbe}. Additional
33	 * configurable properties include:
34	 *
35	 *   port - required port for socket connection
36	 *   timeout - connection timeout (default 1000)
37	 */
38	public class PortProbe extends DefaultProbe {
39	  protected static final Logger log = LoggerFactory.getLogger(PortProbe.class);
40	  private final int port;
41	  private final int timeout;
42	
43	  public PortProbe(int port, int timeout, Map<String, String> props) {
44	    super("Port probe of " + port + " for " + timeout + "ms", props);
45	    this.port = port;
46	    this.timeout = timeout;
47	  }
48	
49	  public static PortProbe create(Map<String, String> props)
50	      throws IOException {
51	    int port = getPropertyInt(props, PORT_PROBE_PORT, null);
52	
53	    if (port >= 65536) {
54	      throw new IOException(PORT_PROBE_PORT + " " + port + " is out of " +
55	          "range");
56	    }
57	
58	    int timeout = getPropertyInt(props, PORT_PROBE_CONNECT_TIMEOUT,
59	        PORT_PROBE_CONNECT_TIMEOUT_DEFAULT);
60	
61	    return new PortProbe(port, timeout, props);
62	  }
63	
64	  /**
65	   * Try to connect to the (host,port); a failure to connect within
66	   * the specified timeout is a failure.
67	   * @param instance role instance
68	   * @return the outcome
69	   */
70	  @Override
71	  public ProbeStatus ping(ComponentInstance instance) {
72	    ProbeStatus status = super.ping(instance);
73	    if (!status.isSuccess()) {
74	      return status;
75	    }
76	
77	    String ip = instance.getContainerStatus().getIPs().get(0);
78	    InetSocketAddress sockAddr = new InetSocketAddress(ip, port);
79	    Socket socket = new Socket();
80	    try {
81	      if (log.isDebugEnabled()) {
82	        log.debug(instance.getCompInstanceName() + ": Connecting " + sockAddr
83	            .toString() + ", timeout=" + MonitorUtils
84	            .millisToHumanTime(timeout));
85	      }
86	      socket.connect(sockAddr, timeout);
87	      status.succeed(this);
88	    } catch (Throwable e) {
89	      String error =
90	          instance.getCompInstanceName() + ": Probe " + sockAddr + " failed";
91	      log.debug(error, e);
92	      status.fail(this, new IOException(error, e));
93	    } finally {
94	      IOUtils.closeSocket(socket);
95	    }
96	    return status;
97	  }
98	}
