40	/**
41	 * Tests for default probe.
42	 */
43	@RunWith(Parameterized.class)
44	public class TestDefaultProbe {
45	  private final DefaultProbe probe;
46	
47	  public TestDefaultProbe(Probe probe) {
48	    this.probe = (DefaultProbe) probe;
49	  }
50	
51	  @Parameterized.Parameters
52	  public static Collection<Object[]> data() {
53	    // test run 1: Default probe checks that container has an IP
54	    Probe p1 = MonitorUtils.getProbe(null);
55	
56	    // test run 2: Default probe with DNS check for component instance hostname
57	    ReadinessCheck rc2 = new ReadinessCheck()
58	        .type(ReadinessCheck.TypeEnum.DEFAULT)
59	        .properties(Collections.singletonMap(
60	            MonitorKeys.DEFAULT_PROBE_DNS_CHECK_ENABLED, "true"));
61	    Probe p2 = MonitorUtils.getProbe(rc2);
62	
63	    // test run 3: Default probe with DNS check using specific DNS server
64	    Map<String, String> props = new HashMap<>();
65	    props.put(MonitorKeys.DEFAULT_PROBE_DNS_CHECK_ENABLED, "true");
66	    props.put(MonitorKeys.DEFAULT_PROBE_DNS_ADDRESS, "8.8.8.8");
67	    ReadinessCheck rc3 = new ReadinessCheck()
68	        .type(ReadinessCheck.TypeEnum.DEFAULT).properties(props);
69	    Probe p3 = MonitorUtils.getProbe(rc3);
70	
71	    return Arrays.asList(new Object[][] {{p1}, {p2}, {p3}});
72	  }
73	
74	  @Test
75	  public void testDefaultProbe() {
76	    // component instance has a good hostname, so probe will eventually succeed
77	    // whether or not DNS checking is enabled
78	    ComponentInstance componentInstance =
79	        createMockComponentInstance("example.com");
80	    checkPingResults(probe, componentInstance, false);
81	
82	    // component instance has a bad hostname, so probe will fail when DNS
83	    // checking is enabled
84	    componentInstance = createMockComponentInstance("bad.dns.test");
85	    checkPingResults(probe, componentInstance, probe.isDnsCheckEnabled());
86	  }
87	
88	  private static void checkPingResults(Probe probe, ComponentInstance
89	      componentInstance, boolean expectDNSCheckFailure) {
90	    // on the first ping, null container status results in failure
91	    ProbeStatus probeStatus = probe.ping(componentInstance);
92	    assertFalse("Expected failure for " + probeStatus.toString(),
93	        probeStatus.isSuccess());
94	    assertTrue("Expected IP failure for " + probeStatus.toString(),
95	        probeStatus.toString().contains(
96	        componentInstance.getCompInstanceName() + ": IP is not available yet"));
97	
98	    // on the second ping, container status is retrieved but there are no
99	    // IPs, resulting in failure
100	    probeStatus = probe.ping(componentInstance);
101	    assertFalse("Expected failure for " + probeStatus.toString(),
102	        probeStatus.isSuccess());
103	    assertTrue("Expected IP failure for " + probeStatus.toString(),
104	        probeStatus.toString().contains(componentInstance
105	            .getCompInstanceName() + ": IP is not available yet"));
106	
107	    // on the third ping, IPs are retrieved and success depends on whether or
108	    // not a DNS lookup can be performed for the component instance hostname
109	    probeStatus = probe.ping(componentInstance);
110	    if (expectDNSCheckFailure) {
111	      assertFalse("Expected failure for " + probeStatus.toString(),
112	          probeStatus.isSuccess());
113	      assertTrue("Expected DNS failure for " + probeStatus.toString(),
114	          probeStatus.toString().contains(componentInstance
115	              .getCompInstanceName() + ": DNS checking is enabled, but lookup" +
116	              " for " + componentInstance.getHostname() + " is not available " +
117	              "yet"));
118	    } else {
119	      assertTrue("Expected success for " + probeStatus.toString(),
120	          probeStatus.isSuccess());
121	    }
122	  }
123	
124	  private static ComponentInstance createMockComponentInstance(String
125	      hostname) {
126	    ComponentInstance componentInstance = mock(ComponentInstance.class);
127	    when(componentInstance.getHostname()).thenReturn(hostname);
128	    when(componentInstance.getCompInstanceName()).thenReturn("comp-0");
129	    when(componentInstance.getContainerStatus())
130	        .thenAnswer(new Answer<ContainerStatus>() {
131	          private int count = 0;
132	
133	          @Override
134	          public ContainerStatus answer(InvocationOnMock invocationOnMock) {
135	            count++;
136	            if (count == 1) {
137	              // first call to getContainerStatus returns null
138	              return null;
139	            } else if (count == 2) {
140	              // second call returns a ContainerStatus with no IPs
141	              ContainerStatus containerStatus = mock(ContainerStatus.class);
142	              when(containerStatus.getIPs()).thenReturn(null);
143	              return containerStatus;
144	            } else {
145	              // third call returns a ContainerStatus with one IP
146	              ContainerStatus containerStatus = mock(ContainerStatus.class);
147	              when(containerStatus.getIPs())
148	                  .thenReturn(Collections.singletonList("1.2.3.4"));
149	              return containerStatus;
150	            }
151	          }
152	        });
153	    return componentInstance;
154	  }
155	}
