25	import java.io.IOException;
26	import java.util.Collections;
27	import java.util.Map;
28	
29	/**
30	 * A probe that checks whether the AM has retrieved an IP for a container.
31	 * Optional parameters enable a subsequent check for whether a DNS lookup can
32	 * be performed for the container's hostname. Configurable properties include:
33	 *
34	 *   dns.check.enabled - true if DNS check should be performed (default false)
35	 *   dns.address - optional IP:port address of DNS server to use for DNS check
36	 */
37	public class DefaultProbe extends Probe {
38	  private final boolean dnsCheckEnabled;
39	  private final String dnsAddress;
40	
41	  public DefaultProbe(Map<String, String> props) {
42	    this("Default probe: IP presence", props);
43	  }
44	
45	  protected DefaultProbe(String name, Map<String, String> props) {
46	    this.dnsCheckEnabled = getPropertyBool(props,
47	        DEFAULT_PROBE_DNS_CHECK_ENABLED,
48	        DEFAULT_PROBE_DNS_CHECK_ENABLED_DEFAULT);
49	    this.dnsAddress = props.get(DEFAULT_PROBE_DNS_ADDRESS);
50	    String additionalName = "";
51	    if (dnsCheckEnabled) {
52	      if (dnsAddress == null) {
53	        additionalName = " with DNS checking";
54	      } else {
55	        additionalName =  " with DNS checking and DNS server address " +
56	            dnsAddress;
57	      }
58	    }
59	    setName(name + additionalName);
60	  }
61	
62	  public static DefaultProbe create() throws IOException {
63	    return new DefaultProbe(Collections.emptyMap());
64	  }
65	
66	  public static DefaultProbe create(Map<String, String> props) throws
67	      IOException {
68	    return new DefaultProbe(props);
69	  }
70	
71	  @Override
72	  public ProbeStatus ping(ComponentInstance instance) {
73	    ProbeStatus status = new ProbeStatus();
74	
75	    ContainerStatus containerStatus = instance.getContainerStatus();
76	    if (containerStatus == null || ServiceUtils.isEmpty(containerStatus
77	        .getIPs())) {
78	      status.fail(this, new IOException(
79	          instance.getCompInstanceName() + ": IP is not available yet"));
80	      return status;
81	    }
82	
83	    String hostname = instance.getHostname();
84	    if (dnsCheckEnabled && !ServiceRegistryUtils.registryDNSLookupExists(
85	        dnsAddress, hostname)) {
86	      status.fail(this, new IOException(
87	          instance.getCompInstanceName() + ": DNS checking is enabled, but " +
88	              "lookup for " + hostname + " is not available yet"));
89	      return status;
90	    }
91	
92	    status.succeed(this);
93	    return status;
94	  }
95	
96	  protected boolean isDnsCheckEnabled() {
97	    return dnsCheckEnabled;
98	  }
99	}
