package org.apache.hadoop.yarn.service.monitor.probe;

import org.apache.hadoop.yarn.api.records.ContainerStatus;
import org.apache.hadoop.yarn.service.component.instance.ComponentInstance;
import org.junit.Test;

import java.io.IOException;
import java.net.ServerSocket;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Tests for the {@link HttpProbe}.
 */
public class TestHttpProbe {

  /**
   * The probe failure message must contain the host the probe actually
   * connected to, not the unresolved ${THIS_HOST} token.
   */
  @Test
  public void testErrorMessageContainsResolvedHost() throws IOException {
    String ip = "127.0.0.1";
    int port = getFreePort();

    Map<String, String> props = new HashMap<>();
    props.put(MonitorKeys.WEB_PROBE_URL,
        "http://${THIS_HOST}:" + port + "/ping");
    props.put(MonitorKeys.WEB_PROBE_CONNECT_TIMEOUT, "100");
    HttpProbe probe = HttpProbe.create(props);

    ProbeStatus status = probe.ping(createMockComponentInstance(ip));
    assertFalse("Expected failure for " + status, status.isSuccess());
    String message = status.toString();
    assertFalse("Unresolved host token in " + message,
        message.contains("${THIS_HOST}"));
    assertTrue("Expected resolved host in " + message,
        message.contains("http://" + ip + ":" + port + "/ping"));
  }

  private static int getFreePort() throws IOException {
    try (ServerSocket socket = new ServerSocket(0)) {
      return socket.getLocalPort();
    }
  }

  private static ComponentInstance createMockComponentInstance(String ip) {
    ComponentInstance componentInstance = mock(ComponentInstance.class);
    when(componentInstance.getHostname()).thenReturn("comp-0.test.local");
    when(componentInstance.getCompInstanceName()).thenReturn("comp-0");
